import {jest} from '@jest/globals';
import {Ajv} from 'ajv';

const validator = new Ajv({strict: false, validateFormats: false});
const compile = jest.spyOn(validator, 'compile');
jest.unstable_mockModule('ajv', () => ({
  Ajv: jest.fn(() => validator),
}));

const {ToolRegistry} = await import('./registry.js');

describe('ToolRegistry static compilation', () => {
  it('compiles a static schema once through the Ajv package entry point across ten calls (spec: specs/hal-engine-tool-input-validation/spec.md#7)', async () => {
    const registry = new ToolRegistry();
    const inputs: Record<string, unknown>[] = [];
    const input = {location: 'Berlin', extra: 42};
    registry.register(
      {
        name: 'weather',
        description: 'Weather by location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async received => {
        inputs.push(received);
        return 'sunny';
      }
    );
    const registrationCompiles = compile.mock.calls.length;

    for (let call = 0; call < 10; call++) {
      await registry.execute('weather', input);
    }

    expect({registrationCompiles, totalCompiles: compile.mock.calls.length, inputs}).toEqual({
      registrationCompiles: 1,
      totalCompiles: 1,
      inputs: Array.from({length: 10}, () => input),
    });
  });
});
EOF
